
CREATE TABLE po_lines (
    id BIGINT AUTO_INCREMENT PRIMARY KEY,
    
    po_number VARCHAR(50) NOT NULL,
    product_code VARCHAR(50) NOT NULL,
    bar_code VARCHAR(50),
    product_full_desc VARCHAR(255),
    store_code VARCHAR(20),
    
    po_total_qty DECIMAL(12,2),
    po_total_case_qty DECIMAL(10,2),
    purchase_price DECIMAL(12,4),          -- Using 4 decimals for precise unit costs
    po_tot_val_at_cp DECIMAL(12,4),
    po_tot_val_at_sp DECIMAL(12,4),
    po_tot_discount_val DECIMAL(12,4),     -- Accommodates values like 4.2163
    
    uom_buying VARCHAR(20),                -- e.g., 'C10'
    uom_selling VARCHAR(20),               -- e.g., 'PCK'
    po_tot_discount_percentage VARCHAR(20), -- e.g., '2.0%'
    
    po_attr JSON DEFAULT NULL,             -- Assuming JSON based on similar headers table
    buying_conversion_factor DECIMAL(10,2), 
    po_org_tot_qty DECIMAL(12,2),
    
    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
    
    -- Indexing foreign keys and commonly searched columns will speed up your Python queries
    INDEX idx_po_number (po_number),
    INDEX idx_product_code (product_code)
);

/*
-- Query: select pl.id, pl.po_number, pl.product_code, pm.unique_product_code as bar_code, pm.product_full_desc, pl.store_code, pl.po_total_qty, pl.po_total_case_qty, pl.purchase_price, pl.po_tot_val_at_cp, pl.po_tot_val_at_sp, pl.po_tot_discount_val, pl.uom_buying, pl.uom_selling, pl.po_tot_discount_percentage, pl.po_attr, pl.buying_conversion_factor, pl.po_org_tot_qty, pl.created_at, pl.updated_at from po_lines pl LEFT JOIN product_masters pm ON pm.product_code = pl.product_code WHERE pl.po_number IN (3969397, 3975366, 4010510, 4013368, 4014862, 4016684, 4016852, 4017234, 4017241, 4017246)
LIMIT 0, 5000

-- Date: 2026-03-20 18:12
*/
